-- Relational Database (e.g., PostgreSQL)
CREATE TABLE trades (
    trade_id BIGSERIAL PRIMARY KEY,
    timestamp TIMESTAMPTZ NOT NULL,
    instrument_id VARCHAR(50) NOT NULL,
    buy_sell_indicator CHAR(1) NOT NULL, -- 'B' for Buy, 'S' for Sell
    price NUMERIC(18, 8) NOT NULL,
    quantity BIGINT NOT NULL,
    trader_id VARCHAR(100) NOT NULL,
    client_id VARCHAR(100),
    exchange_code VARCHAR(10),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX idx_trades_timestamp ON trades (timestamp);
CREATE INDEX idx_trades_instrument_id ON trades (instrument_id);
CREATE INDEX idx_trades_trader_id ON trades (trader_id);

CREATE TABLE alerts (
    alert_id BIGSERIAL PRIMARY KEY,
    trade_id BIGINT REFERENCES trades(trade_id),
    suspicious_pattern_type VARCHAR(100) NOT NULL,
    risk_score NUMERIC(5, 4) NOT NULL,
    detection_timestamp TIMESTAMPTZ DEFAULT NOW(),
    status VARCHAR(20) DEFAULT 'New' NOT NULL, -- e.g., New, Investigating, Resolved, False Positive
    analyst_id VARCHAR(100),
    notes TEXT,
    resolved_at TIMESTAMPTZ
);

CREATE INDEX idx_alerts_detection_timestamp ON alerts (detection_timestamp);
CREATE INDEX idx_alerts_status ON alerts (status);
CREATE INDEX idx_alerts_trade_id ON alerts (trade_id);

CREATE TABLE market_news (
    news_id BIGSERIAL PRIMARY KEY,
    source VARCHAR(100) NOT NULL,
    published_at TIMESTAMPTZ NOT NULL,
    headline TEXT NOT NULL,
    content TEXT,
    instruments_mentioned VARCHAR(200)[],
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX idx_market_news_published_at ON market_news (published_at);
CREATE INDEX idx_market_news_instruments ON market_news USING GIN (instruments_mentioned);

